DO $$
BEGIN
  UPDATE members SET tier = 'champion' WHERE total_posts >= 100 AND response_rate >= 0.75;
  UPDATE members SET tier = 'contributor' WHERE total_posts >= 30 AND total_posts < 100;
  UPDATE members SET bonus_points = total_posts * 5 WHERE tier = 'champion';
  UPDATE members SET bonus_points = total_posts * 2 WHERE tier = 'contributor';
END $$;
SELECT * FROM members ORDER BY member_id;
